{
  "title": "A Tight-Knit Kyoto Day",
  "summary": "A slower, closer day around the northern and eastern temples, with a quiet vegan lunch and an evening wander.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Kept as the must-do. Shoes off, phone down, eyes up for the golden pavilion."
    },
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "A free, gentle stroll between temples. The deer will cope without you; the blossoms won't wait."
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "Close to the path and easier on the budget than the far museum. Worth one message."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "A vegan set lunch that suits everyone, tucked near the temples. Tentative usually means a dentist; this is not that."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "Free, open all day, and a short hop from the temples. Good for the photo spot taste."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "An evening wander for the night owl, close to Gion. Keep the phone down and the eyes up."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A vegetarian-friendly dinner near the evening stop, kinder to the budget than the old ryokan meal."
    }
  ]
}
